#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs.Entities;
using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Audios;
using MVZ2Logic.Definitions;
using MVZ2Logic.Entities;
using MVZ2Logic.HeldItems;
using MVZ2Logic.Inputs;
using MVZ2Logic.Level;
using PVZEngine.Grids;

namespace MVZ2.GameContent.HeldItems
{
    [AutoHeldItemBehaviourDefinition(VanillaHeldItemBehaviourNames.teleporterEvocation)]
    public class TeleporterEvocationHeldItemBehaviour : ClickContraptionTargetHeldItemBehaviour
    {
        public TeleporterEvocationHeldItemBehaviour(string nsp, string name) : base(nsp, name)
        {
        }

        public override HeldHighlight GetHighlight(IHeldItemTarget target, IHeldItemData data, PointerInteractionData pointer)
        {
            if (target is not HeldItemTargetGrid targetGrid)
                return HeldHighlight.None;

            var width = Teleporter_Evoke.WIDTH;
            var height = Teleporter_Evoke.HEIGHT;
            var xOffset = Teleporter_Evoke.X_OFFSET;
            var yOffset = Teleporter_Evoke.Y_OFFSET;
            List<LawnGrid> grids = new List<LawnGrid>();
            var level = targetGrid.GetLevel();
            for (int x = 0; x < width; x++)
            {
                for (int y = 0; y < height; y++)
                {
                    var grid = level.GetGrid(targetGrid.Target.Column + x + xOffset, targetGrid.Target.Lane + y + yOffset);
                    if (grid == null)
                        continue;
                    grids.Add(grid);
                }
            } 
            return HeldHighlight.Green(grids);
        }
        protected override void OnUseOnGrid(HeldItemTargetGrid targetGrid, IHeldItemData data, PointerInteractionData pointerParams)
        {
            var level = targetGrid.GetLevel();
            var entity = GetEntity(level, data);
            if (entity == null)
                return;
            Teleporter_Evoke.TeleportTeam(entity, targetGrid.Target);
        }
    }
}
